// Language of the comments / documentation inside generated code.
// Project Settings → コメントの言語: auto (= the language Codiram is shown in) / ja / en.
import { getLang } from './i18n.js';

export function commentLang(project) {
  const v = project?.settings?.commentLang;
  return v === 'ja' || v === 'en' ? v : getLang() === 'ja' ? 'ja' : 'en';
}
/** cm(project)('日本語', 'English') picks the text for the comment language */
export const cm = (project) => { const ja = commentLang(project) === 'ja'; return (j, e) => (ja ? j : e); };

/** the "generated by Codiram" note used in file headers: note(project, 'JavaScript') */
export const noteFor = (project, language) => cm(project)(`Codiram が生成した ${language} コードです。自由に編集できます。`, `Generated by Codiram. Plain ${language}: edit freely.`);

// English comments that the runtime / generator writes -> Japanese
const JA = {
  'logic first, so we know which optional runtime modules are needed': '先にロジックを生成し、必要なランタイムモジュールを把握する',
  '===== 1. Data models =====': '===== 1. データモデル =====',
  '===== 2. State =====': '===== 2. 状態(変数) =====',
  '===== 3. Runtime helpers =====': '===== 3. ランタイム補助関数 =====',
  '===== 4. Logic (generated from blocks) =====': '===== 4. ロジック(ブロックから生成) =====',
  '===== 4b. Custom JavaScript (Project Settings) =====': '===== 4b. カスタム JavaScript(プロジェクト設定) =====',
  '===== 5. Start =====': '===== 5. 起動 =====',
  'table being edited: not re-rendered while the user types': '編集中のテーブル(入力中は再描画しない)',
  '---- storage ----': '---- 保存 ----', '---- variables ----': '---- 変数 ----', '---- UI helpers ----': '---- UI 補助 ----',
  '"{name}", "{items.length}", "{User[0].name}" ...': '"{name}"、"{items.length}"、"{User[0].name}" などの埋め込み',
  '---- rendering of bound elements ----': '---- バインドされた要素の描画 ----',
  "Relation fields store the _id of a row of another model; show that row's first text field instead": 'リレーション項目は他のモデルの行の _id を保存する。表示では、その行の最初の文字列項目を使う',
  '---- data operations ----': '---- データ操作 ----', '---- timers, keys, element helpers ----': '---- タイマー・キー・要素の補助 ----',
  '---- start up ----': '---- 起動処理 ----', '---- charts ----': '---- グラフ ----', '---- map ----': '---- 地図 ----',
  '---- list / object helpers ----': '---- 配列・オブジェクトの補助 ----', '---- date / time helpers ----': '---- 日付・時刻の補助 ----',
  '---- animation helpers ----': '---- アニメーションの補助 ----', '---- sound ----': '---- サウンド ----',
  '---- game engine: sprites, input, collisions, frame loop ----': '---- ゲームエンジン: スプライト・入力・衝突判定・フレームループ ----',
  '---- canvas drawing ----': '---- キャンバス描画 ----', '---- CSV ----': '---- CSV ----', '---- file input ----': '---- ファイル入力 ----',
  '---- WebSocket ----': '---- WebSocket ----', '---- system helpers ----': '---- システム補助 ----',
  'storage unavailable': '保存領域が使えない', 'ignore': '無視', 'blocked until the user interacts': 'ユーザー操作があるまでブロックされる',
  'Base styles for Codiram components': 'Codiram 部品の基本スタイル', '---- Component styles ----': '---- 部品ごとのスタイル ----',
  '---- Animations ----': '---- アニメーション ----', '---- Custom CSS (Project Settings) ----': '---- カスタム CSS(プロジェクト設定) ----',
  'Initial data (edit in Codiram\'s Data view, or here).': '初期データ(Codiram の Data 画面、またはここで編集できます)。',
};
const JA_RE = Object.keys(JA).sort((a, b) => b.length - a.length);

/** Japanese version of the comments in generated JS / CSS / data text */
export function localizeComments(text, project) {
  if (commentLang(project) !== 'ja') return text;
  let out = text;
  for (const en of JA_RE) if (out.includes(en)) out = out.split(en).join(JA[en]);
  return out.replace('generated by Codiram. Plain JavaScript: edit freely.', 'Codiram が生成した JavaScript コードです。自由に編集できます。');
}
